local ChestMaker = {}
local PRODUCTS = {
    simple_pine_chest = { name = "Preprost borov skrinja", woodCost = 3, ironCost = 1, time = 4, cost = 70, beauty = 20, happiness = 1, storage = 25, description = "Preprost borov skrinja za hišo." },
    carved_oak_chest = { name = "Izrezljana hrastov skrinja", woodCost = 3, ironCost = 1, leatherCost = 1, time = 7, cost = 200, beauty = 35, happiness = 2, storage = 40, prestige = 2, description = "Izrezljana hrastov skrinja za trgovce." },
    silver_banded_chest = { name = "Srebrnopasna skrinja", woodCost = 3, silverCost = 1, ironCost = 1, leatherCost = 1, time = 10, cost = 480, beauty = 50, happiness = 2, storage = 55, prestige = 6, description = "Srebrnopasna skrinja za plemiče." },
    gold_trimmed_chest = { name = "Zlatookrasna skrinja", woodCost = 4, goldCost = 1, silverCost = 1, ironCost = 1, leatherCost = 1, time = 14, cost = 1100, beauty = 65, happiness = 3, storage = 70, prestige = 14, description = "Zlatookrasna skrinja za visoke plemiče." },
    jewel_lock_chest = { name = "Draguljnoključna skrinja", woodCost = 4, goldCost = 2, silverCost = 1, ironCost = 1, leatherCost = 1, jewelCost = 1, time = 18, cost = 2500, beauty = 80, happiness = 5, storage = 85, prestige = 27, description = "Skrinja z draguljnim ključavnico za visoko plemstvo." },
    royal_grand_chest = { name = "Kraljevski veliki skrinja", woodCost = 6, goldCost = 3, silverCost = 2, ironCost = 1, leatherCost = 1, jewelCost = 2, pearlCost = 2, time = 25, cost = 5500, beauty = 95, happiness = 12, storage = 100, prestige = 58, description = "Velika kraljevska skrinja z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    chest_workshop = { name = "Skrinjarska delavnica", cost = { gold = 260, wood = 160, stone = 100, iron = 4 }, upkeep = 6, qualityBonus = 5 },
    coffer_loft = { name = "Skrinjarska podstrešje", cost = { gold = 950, wood = 320, stone = 220, silver = 6, leather = 6 }, upkeep = 22, qualityBonus = 18 },
    master_chest_atelier = { name = "Mojstrski skrinjarski atelje", cost = { gold = 2700, wood = 380, stone = 480, silver = 30, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_chest_palace = { name = "Kraljevska skrinjarska palača", cost = { gold = 11500, wood = 600, stone = 760, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
ChestMaker.woodStock = 20; ChestMaker.ironStock = 10; ChestMaker.leatherStock = 10; ChestMaker.silverStock = 6; ChestMaker.goldStock = 6; ChestMaker.jewelStock = 4; ChestMaker.pearlStock = 4
ChestMaker.productStock = {}; ChestMaker.buildings = {}; ChestMaker.maker = nil; ChestMaker.activeMaking = {}; ChestMaker.totalProducts = 0; ChestMaker.dayTimer = 0
function ChestMaker.init() ChestMaker.woodStock=20; ChestMaker.ironStock=10; ChestMaker.leatherStock=10; ChestMaker.silverStock=6; ChestMaker.goldStock=6; ChestMaker.jewelStock=4; ChestMaker.pearlStock=4; ChestMaker.productStock={}; ChestMaker.buildings={}; ChestMaker.maker=nil; ChestMaker.activeMaking={}; ChestMaker.totalProducts=0; ChestMaker.dayTimer=0; print("[ChestMaker] Royal Chest Maker System initialized (6 products, 4 buildings)") end
function ChestMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ChestMaker.maker={name=n or ("Skrinjar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Skrinjar najet: %s (spretnost: %d)",ChestMaker.maker.name,s),"success") end; return true end
function ChestMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ChestMaker.build(id) local ok,e=ChestMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ChestMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ChestMaker.getQualityBonus() local b=0; for _,bd in ipairs(ChestMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ChestMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and ChestMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and ChestMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.leatherCost and ChestMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and ChestMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ChestMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ChestMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and ChestMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #ChestMaker.buildings==0 then return false,"Potrebna skrinjarska delavnica" end; if not ChestMaker.maker then return false,"Potreben skrinjar" end; return true end
function ChestMaker.make(pt,qty) qty=qty or 1; local ok,e=ChestMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then ChestMaker.woodStock=ChestMaker.woodStock-d.woodCost*qty end; if d.ironCost then ChestMaker.ironStock=ChestMaker.ironStock-d.ironCost*qty end; if d.leatherCost then ChestMaker.leatherStock=ChestMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then ChestMaker.silverStock=ChestMaker.silverStock-d.silverCost*qty end; if d.goldCost then ChestMaker.goldStock=ChestMaker.goldStock-d.goldCost*qty end; if d.jewelCost then ChestMaker.jewelStock=ChestMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then ChestMaker.pearlStock=ChestMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if ChestMaker.maker then t=math.max(1,t-math.floor(ChestMaker.maker.skill/13)) end; table.insert(ChestMaker.activeMaking,{id="chest_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,storage=d.storage or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ChestMaker.completeMaking(m) local q=1.0+(ChestMaker.getQualityBonus()/100); if ChestMaker.maker then q=q+(ChestMaker.maker.skill/140) end; q=math.min(2.5,q); ChestMaker.productStock[m.productType]=(ChestMaker.productStock[m.productType] or 0)+m.quantity; ChestMaker.totalProducts=ChestMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ChestMaker.maker then ChestMaker.maker.itemsMade=ChestMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then ChestMaker.maker.skill=math.min(100,ChestMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Skrinja izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"chest.completed",{productName=m.productName,beauty=m.beauty,storage=m.storage,prestige=m.prestige,happiness=m.happiness}) end end
function ChestMaker.update(dt) if not _G.state then return end; ChestMaker.dayTimer=ChestMaker.dayTimer+dt; if ChestMaker.dayTimer>=30 then ChestMaker.dayTimer=0; for i=#ChestMaker.activeMaking,1,-1 do local m=ChestMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ChestMaker.completeMaking(m); table.remove(ChestMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ChestMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ChestMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ChestMaker.getStats() return {woodStock=ChestMaker.woodStock,ironStock=ChestMaker.ironStock,leatherStock=ChestMaker.leatherStock,silverStock=ChestMaker.silverStock,goldStock=ChestMaker.goldStock,jewelStock=ChestMaker.jewelStock,pearlStock=ChestMaker.pearlStock,productStock=ChestMaker.productStock,numBuildings=#ChestMaker.buildings,hasMaker=ChestMaker.maker~=nil,makerName=ChestMaker.maker and ChestMaker.maker.name or "—",makerSkill=ChestMaker.maker and ChestMaker.maker.skill or 0,activeMaking=#ChestMaker.activeMaking,totalProducts=ChestMaker.totalProducts} end
return ChestMaker
